 "content": "from math import gcd
from functools import reduce


def transform(grid):
    h, w = len(grid), len(grid[0])
    cells8 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    key = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] not in (0, 8)]
    r0, r1 = min(r for r, c, v in key), max(r for r, c, v in key)
    c0, c1 = min(c for r, c, v in key), max(c for r, c, v in key)
    pattern = [[0 for _ in range(c0, c1 + 1)] for _ in range(r0, r1 + 1)]
    for r, c, v in key:
        pattern[r - r0][c - c0] = v

    # The key is turned clockwise to obtain the coloring of the large tiled shape.
    rotated = [list(row) for row in zip(*pattern[::-1])]

    runs = []
    for r in range(h):
        run = 0
        for c in range(w + 1):
            if c < w and grid[r][c] == 8:
                run += 1
            elif run:
                runs.append(run)
                run = 0
    for c in range(w):
        run = 0
        for r in range(h + 1):
            if r < h and grid[r][c] == 8:
                run += 1
            elif run:
                runs.append(run)
                run = 0
    scale = reduce(gcd, runs)
    min_r = min(r for r, c in cells8)
    min_c = min(c for r, c in cells8)

    out = [row[:] for row in grid]
    for r, c in cells8:
        tr, tc = (r - min_r) // scale, (c - min_c) // scale
        out[r][c] = rotated[tr][tc]
    return out
